/**
 * Loads web/ao-bin-dumps/shopcategories.json - the localized Category -> Sub-type taxonomy
 * generated by tools/generate-shop-categories.ts from Albion's own items.json shopcategories
 * tree + localization.json tuids. Powers the Market page's cascading Category/Sub-type filter
 * (mirrors the in-game marketplace's own cascading dropdown, not a flat guessed list).
 *
 * Shape on disk: { [categoryId]: { label: string, subcategories: { [subId]: string } } }
 * Key order in the JSON matches the game's own shopcategories tree order, so callers should
 * preserve iteration order rather than re-sorting alphabetically.
 */
import {CATEGORIES} from '../constants/LoggerConstants.js';

let cache = null;

/**
 * Fetch and cache shopcategories.json. Safe to call repeatedly - only fetches once.
 * @param {string} [jsonPath]
 * @returns {Promise<Record<string, {label: string, subcategories: Record<string, string>}>>}
 */
export async function load(jsonPath = '/ao-bin-dumps/shopcategories.json') {
    if (cache) return cache;

    const response = await fetch(jsonPath, {cache: 'no-cache'});
    if (!response.ok) {
        throw new Error(`Failed to fetch shopcategories.json: ${response.status}`);
    }
    cache = await response.json();
    window.logger?.info(CATEGORIES.SYSTEM, 'ShopCategoriesLoaded', {count: Object.keys(cache).length});
    return cache;
}

/**
 * @returns {Array<{id: string, label: string}>} top-level categories, in taxonomy order
 */
export function getCategories() {
    if (!cache) return [];
    return Object.entries(cache).map(([id, entry]) => ({id, label: entry.label}));
}

/**
 * @param {string} categoryId
 * @returns {Array<{id: string, label: string}>} subcategories for one category, in taxonomy order
 */
export function getSubcategories(categoryId) {
    if (!cache || !categoryId || !cache[categoryId]) return [];
    return Object.entries(cache[categoryId].subcategories).map(([id, label]) => ({id, label}));
}
